package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import java.util.TreeSet;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.holiday.HolidayService;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.WatchService;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateChain;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.settings.SettingsService;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.sheet.TodayChanged;
import net.officefloor.hq.app.voidreason.VoidReasonService;
import org.springframework.context.event.EventListener;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** The claims people make on a sheet. */
@Service
public class ClaimService {

    /** The number sequence of claims in no period. */
    private static final String NO_PERIOD = "X";

    /** The days after its settlement within which a steward may void a SETTLED claim. */
    private static final int VOID_SETTLED_DAYS = 7;

    private final ClaimRepository claims;
    private final ClaimTagRepository tags;
    private final PersonRepository people;
    private final RateChain rates;
    private final PeriodRepository periods;
    private final SheetService sheets;
    private final RollupService rollup;
    private final SettingsService settings;
    private final WatchService watches;
    private final HolidayService holidays;
    private final VoidReasonService voidReasons;
    private final Audit audit;

    public ClaimService(ClaimRepository claims, ClaimTagRepository tags, PersonRepository people, RateChain rates,
            PeriodRepository periods, SheetService sheets, RollupService rollup, SettingsService settings,
            WatchService watches, HolidayService holidays, VoidReasonService voidReasons, Audit audit) {
        this.claims = claims;
        this.tags = tags;
        this.people = people;
        this.rates = rates;
        this.periods = periods;
        this.sheets = sheets;
        this.rollup = rollup;
        this.settings = settings;
        this.watches = watches;
        this.holidays = holidays;
        this.voidReasons = voidReasons;
        this.audit = audit;
    }

    /** All the claims on the sheet, newest first. */
    @Transactional(readOnly = true)
    public List<Claim> list(String sheetId) {
        return claims.findBySheetIdOrderByListedDescIdDesc(sheetId);
    }

    /**
     * Adds a claim for the person; a missing date takes the sheet's entry date, or its today when that is blank. Its
     * due-by is fixed as the terms-th business day after its date, skipping weekends and the sheet's holidays then, and its period is the one its due-by falls in: one whose
     * due-by falls in a soft-closed period is a late entry. Refused when its due-by falls in a closed period or when
     * it is dated after the person's retirement date, and a correction (a negative amount) unless it corrects a settled claim of
     * the person.
     */
    @Transactional
    public Claim add(String by, String sheetId, Long personId, BigDecimal amount, LocalDate date, String note,
            String corrects) {
        return add(by, sheetId, personId, amount, date, note, corrects, null);
    }

    /** Adds a claim as {@link #add(String, String, Long, BigDecimal, LocalDate, String, String, String, String)} does, with no tags. */
    @Transactional
    public Claim add(String by, String sheetId, Long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref) {
        return add(by, sheetId, personId, amount, date, note, corrects, ref, null);
    }

    /**
     * Adds a claim as {@link #add(String, String, Long, BigDecimal, LocalDate, String, String)} does, carrying the
     * external reference (stripped; blank for none). Refused too when the reference is already used on the sheet,
     * comparing without regard to case. Its tags (comma separated) are trimmed, lower-cased and kept once each.
     */
    @Transactional
    public Claim add(String by, String sheetId, Long personId, BigDecimal amount, LocalDate date, String note,
            String corrects, String ref, String tagged) {
        LocalDate on = dateOrEntryDate(sheetId, date);
        Person person = person(sheetId, personId);
        int terms = termsFor(sheetId, person, on);
        LocalDate dueBy = holidays.dueBy(sheetId, on, terms);
        refuseInClosedPeriod(sheetId, dueBy);
    /** The claim, locked; refused when its due-by falls in a closed period. */
    private Claim lockedClaim(String sheetId, Long id) {
        // the sheet is locked before the claim, in the order a period closing takes them
        sheets.lock(sheetId);
        Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
        refuseInClosedPeriod(sheetId, claim.getDueBy());
        return claim;
    }

    /**
     * Gives the claim being opened its number: while the sheet's period numbering from is set and its today is on or
     * after it, the next in the sequence of the period the claim's due-by falls in (X for none), else the sheet's next.
     * The sheet is locked, so two claims opened at once never get the same one.
     */
    private void number(String sheetId, Claim claim) {
        if (!numbersByPeriod(sheetId)) {
            claim.setNumber(String.valueOf(sheets.nextClaimNumber(sheetId)));
            return;
        }
        String sequence = sequenceOn(sheetId, claim.getDueBy());
        Long last = claims.lastInSequence(sheetId, sequence);
        claim.numberIn(sequence, last == null ? 1 : last + 1);
    }

    /**
     * Gives a numbered claim the next number in the sequence it would be numbered in now; its old one is retired, so it
     * is never given again (a sheet number never is: the sheet's count only rises).
     */
    private void renumber(String sheetId, Claim claim) {
        if (claim.getNumberSequence() != null) {
            claims.retireNumber(sheetId, claim.getNumberSequence(), claim.getNumberInSequence());
        }
        claim.clearNumber();
        number(sheetId, claim);
    }

    /** Whether the sheet numbers claims by period: its period numbering from is set and its today on or after it. */
    private boolean numbersByPeriod(String sheetId) {
        Sheet sheet = sheets.load(sheetId);
        LocalDate from = sheet.getPeriodNumberingFrom();
        return from != null && !sheet.getToday().isBefore(from);
    }

    /** The number sequence of a claim due by the date: the name of the period it is in, or X for none. */
    private String sequenceOn(String sheetId, LocalDate date) {
        return periods.findFirstBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId, date, date)
                .map(Period::getName).orElse(NO_PERIOD);
    }

    /**
     * The claim's rate figure: at the rate its person's grade in force on its date has in force on that date, rounded
     * as the sheet's policy date decides for it, with no floor; null (n/a) with none.
     */
    public BigDecimal rateFigure(String sheetId, Person person, Claim claim) {
        Sheet sheet = sheets.load(sheetId);
        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
        return rates.findInForce(sheetId, person.gradeOn(claim.getDate()), claim.getDate()).map(Rate::getPct)
                .map(pct -> dueOn(claim.getAmount(), pct, rounding)).orElse(null);
    }

    /** What a candidate rate for a grade would change: how many claims would show a different due, and by how much. */
    public record RatePreview(int count, BigDecimal diff) {
    }

    /**
     * Previews the grade's rate at the percent on every date, saving nothing: the OPEN and PENDING claims whose
     * person has the grade in force on the claim's date and whose due would differ, and the sum of new due minus
     * current due (an n/a due counts as 0.00). A claim bound by a statement does not change.
     */
    @Transactional(readOnly = true)
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.util.ArrayDeque;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateChain;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * The figures a sheet shows: each person's claimed and due-total, and the sheet's totals. A change takes a
 * {@link #snapshot} before it and calls {@link #recordChanges} after it, so the audit gets one ROLLUP line per person
 * whose figures (claimed, due-total, overdue-total) moved (in the order they were added) and a TOTALS line when the sheet's totals moved.
 */
@Service
public class RollupService {

    /** One person's figures; a null due-total is n/a. The overdue-total sums their overdue claims' dues. */
    public record Figures(String name, BigDecimal claimed, BigDecimal dueTotal, BigDecimal overdueTotal) {
    }

    /** The figures of every person on a sheet, by person id in the order they were added, and the sheet's totals. */
    public record Snapshot(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal,
            BigDecimal overdueTotal) {
    }

    /** Figures added up over sheets: their people, and each sheet's due-total and overdue-total. */
    public record Consolidated(int peopleCount, BigDecimal dueTotal, BigDecimal overdueTotal) {
    }

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateChain rates;
    private final SheetRepository sheets;
    private final Audit audit;

    public RollupService(PersonRepository people, ClaimRepository claims, RateChain rates, SheetRepository sheets,
            Audit audit) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's figures as the store holds them now (as the screen computes them). */
    public Snapshot snapshot(String sheetId) {
        claims.flush();
        Sheet sheet = sheets.findById(sheetId).orElse(null);
        LocalDate today = sheet == null ? null : sheet.getToday();
        Map<String, List<Rate>> byGrade = new HashMap<>();
        for (Rate r : rates.applying(sheetId)) {
            byGrade.computeIfAbsent(r.getGrade(), g -> new ArrayList<>()).add(r);
        }
        Map<Long, List<Claim>> claimsBy = new HashMap<>();
        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
            if (c.getStatus().counts()) {
                claimsBy.computeIfAbsent(c.getPersonId(), id -> new ArrayList<>()).add(c);
            }
        }
        Map<Long, Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = ZERO;
        List<BigDecimal> dues = new ArrayList<>();
        List<BigDecimal> overdues = new ArrayList<>();
        for (Person p : people.findBySheetIdOrderByIdAsc(sheetId)) {
            // an open claim dated within one of the person's holds counts in no live total, unless a statement binds it;
            // nor does one deferred on the sheet's today
            List<Claim> counted = claimsBy.getOrDefault(p.getId(), List.of()).stream()
                    .filter(c -> p.countsLive(c, today)).toList();
            BigDecimal claimed = ZERO;
            BigDecimal due = ZERO;
            BigDecimal overdue = ZERO;
            boolean kept = false;
            // the grades whose rate today decides n/a: the one in force today and each counted claim's
            Set<String> grades = new HashSet<>();
            grades.add(p.gradeOn(today));
            for (Claim c : counted) {
                grades.add(p.gradeOn(c.getDate()));
                claimed = claimed.add(c.getAmount());
                kept |= c.getSettledDue() != null || (c.isBound() && c.getStatedDue() != null);
                // the claim's rate is the one its person's grade in force on its date has
                BigDecimal figure = figure(c, byGrade.getOrDefault(p.gradeOn(c.getDate()), List.of()), sheet);
                if (c.getSettledDue() == null) {
                    figure = ClaimService.liveDue(figure, c, p, sheet, c.getStatus().isOpen());
                }
                if (figure != null) {
                    kept = true;
                    due = due.add(figure);
                    if (isOverdue(c, p, sheet, today)) {
                        overdue = overdue.add(figure);
                    }
                }
            }
            // with no rate in force today for any of those grades and no claim with a figure (kept, or live at a
            // rate that has since ended), the due-total is n/a
            if (!kept && (today == null || grades.stream()
                    .allMatch(g -> Rate.inForce(byGrade.getOrDefault(g, List.of()), today) == null))) {
                due = null;
            }
            // the due-total is at most the sheet's cap
            if (sheet != null) {
                due = sheet.capped(due);
            }
            figures.put(p.getId(), new Figures(p.getName(), claimed, due, overdue));
            claimedTotal = claimedTotal.add(claimed);
            overdues.add(overdue);
            if (due != null) {
                dues.add(due);
            }
        }
        return new Snapshot(figures, claimedTotal, trimmedSum(dues), trimmedSum(overdues));
    }

    /**
     * The sheet's descendants' figures added up: each sheet naming it as parent, their children, and so on, each
     * sheet counted once and the sheet itself left out (the screen adds its own figures as it shows them).
     */
    @Transactional(readOnly = true)
    public Consolidated descendants(String sheetId) {
        Set<String> seen = new HashSet<>(Set.of(sheetId));
        ArrayDeque<String> toVisit = new ArrayDeque<>(List.of(sheetId));
        int peopleCount = 0;
        BigDecimal due = ZERO;
        BigDecimal overdue = ZERO;
        while (!toVisit.isEmpty()) {
            for (Sheet child : sheets.findByParentIdOrderByIdAsc(toVisit.poll())) {
                if (!seen.add(child.getId())) {
                    continue;
                }
                toVisit.add(child.getId());
                Snapshot s = snapshot(child.getId());
                peopleCount += s.people().size();
                due = due.add(s.dueTotal());
                overdue = overdue.add(s.overdueTotal());
            }
        }
        return new Consolidated(peopleCount, due, overdue);
    }

    /** The sheet-total of the people's figures: with three or more, the single highest and lowest are left out. */
    static BigDecimal trimmedSum(List<BigDecimal> figures) {
        BigDecimal sum = figures.stream().reduce(ZERO, BigDecimal::add);
        if (figures.size() >= 3) {
            sum = sum.subtract(Collections.max(figures)).subtract(Collections.min(figures));
        }
        return sum;
    }

    /** Records, once the change commits, a SNAPSHOT line per person with their due-total in the given snapshot. */
    public void recordSnapshot(String by, String sheetId, Snapshot snapshot) {
        for (Figures f : snapshot.people().values()) {
            audit.recordOnCommit("SNAPSHOT sheet=" + sheetId + " by=" + by + " name=" + f.name() + " due-total="
                    + text(f.dueTotal()));
        }
    }

    /**
     * Records, once the change commits, a ROLLUP line for each person whose figures differ from the snapshot taken
     * before the change (a person new since then counts as changed), then a TOTALS line when the sheet's totals moved.
     */
    public void recordChanges(String by, String sheetId, Snapshot before) {
        Snapshot after = snapshot(sheetId);
        String head = " sheet=" + sheetId + " by=" + by;
        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
            Figures was = before.people().get(e.getKey());
            Figures now = e.getValue();
            if (was != null && was.claimed().equals(now.claimed()) && Objects.equals(was.dueTotal(), now.dueTotal())
                    && was.overdueTotal().equals(now.overdueTotal())) {
                continue;
            }
            audit.recordOnCommit("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed().toPlainString()
                    + " due-total=" + text(now.dueTotal()) + " overdue-total=" + now.overdueTotal().toPlainString());
        }
        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
                || !before.overdueTotal().equals(after.overdueTotal())) {
            audit.recordOnCommit("TOTALS" + head + " claimed-total=" + after.claimedTotal().toPlainString()
                    + " due-total=" + after.dueTotal().toPlainString() + " overdue-total="
                    + after.overdueTotal().toPlainString());
        }
    }

    /**
     * The figure of a claim: its settled due, else the one a statement bound it to, else its rate figure (no floor),
     * rounded as the sheet's policy date decides for it.
     */
    private static BigDecimal figure(Claim c, List<Rate> rates, Sheet sheet) {
        if (c.getSettledDue() != null) {
            return c.getSettledDue();
        }
        if (c.isBound()) {
            return c.getStatedDue();
        }
        Rate rate = Rate.inForce(rates, c.getDate());
        return rate == null ? null : ClaimService.dueOn(c.getAmount(), rate.getPct(), sheet.roundingOn(c.getRoundsOn()));
    }

    /**
     * Whether a claim is overdue: open (or pending), not deferred, and its due-by plus its grace (see
     * {@link ClaimService#lateFrom}) is before the sheet's today.
     */
    private static boolean isOverdue(Claim c, Person p, Sheet sheet, LocalDate today) {
        return c.getStatus().isOpen() && today != null && !c.isDeferredOn(today) && c.getDueBy() != null
                && ClaimService.lateFrom(c, p, sheet).isBefore(today);
    }

    private static String text(BigDecimal value) {
        return value == null ? "n/a" : value.toPlainString();
    }
}

