package net.officefloor.hq.app.rollup;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The figures of a sheet's descendants, which the screen adds to its own for the consolidated figures. */
@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/descendants")
public class RollupController {

    /** The descendants' figures added up: the number of people, and the due-totals and overdue-totals, two decimals. */
    public record ConsolidatedView(int peopleCount, String dueTotal, String overdueTotal) {
        static ConsolidatedView of(RollupService.Consolidated c) {
            return new ConsolidatedView(c.peopleCount(), c.dueTotal().toPlainString(), c.overdueTotal().toPlainString());
        }
    }

    private final RollupService service;

    public RollupController(RollupService service) {
        this.service = service;
    }

    @GetMapping("/figures")
    public ConsolidatedView figures(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String sheetId) {
        return ConsolidatedView.of(service.descendants(sheetId));
    }
}
import { HttpClient } from '@angular/common/http';
import { Component, computed, effect, inject, input, signal, untracked } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { sumSkippingNa } from '../rates/rates';

// The figures of the sheet's descendants (the sheets naming it as parent, theirs, and so on), added up by the store.
interface DescendantFigures {
  peopleCount: number;
  dueTotal: string;
  overdueTotal: string;
}

// The figures over the sheet and all its descendants: the sheet's own, as it shows them, plus each descendant's.
@Component({
  selector: 'app-consolidated',
  template: `
    <section aria-label="Consolidated figures">
      <h2>Consolidated (this sheet and its descendants)</h2>
      <dl>
        <dt>People</dt>
        <dd data-testid="consolidated-people-count">{{ peopleCount() }}</dd>
        <dt>Due</dt>
        <dd data-testid="consolidated-due-total">{{ dueTotal() }}</dd>
        <dt>Overdue</dt>
        <dd data-testid="consolidated-overdue-total">{{ overdueTotal() }}</dd>
      </dl>
    </section>
  `,
}
 */
@Component
public class AsOfGuard implements HandlerInterceptor {

    /** The request header carrying the date the screen shows the sheet as of (yyyy-mm-dd). */
    public static final String HEADER = "X-As-Of";

    private final AsOfService asOf;

    public AsOfGuard(AsOfService asOf) {
        this.asOf = asOf;
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        String header = request.getHeader(HEADER);
        String sheetId = ViewerGuard.sheetId(request);
        if (header == null || header.isBlank() || !(handler instanceof HandlerMethod method) || sheetId == null) {
            return true;
        }
        LocalDate day;
        try {
            day = LocalDate.parse(header.trim());
        } catch (DateTimeParseException e) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The as-of date is not a date.");
        }
        if (!HttpMethod.GET.matches(request.getMethod()) && !method.hasMethodAnnotation(AsOfReads.class)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT,
                    "The sheet is shown as of a date; nothing on it can change.");
        }
        AsOfContext.enter(asOf.storeAsOf(sheetId, day));
        return true;
    }

    @Override
    public void afterCompletion(HttpServletRequest request, HttpServletResponse response, Object handler,
            Exception ex) {
        AsOfContext.leave();
    }
}

